package configurator;

import java.io.BufferedReader;
import java.io.FileReader;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import com.ib.client.Contract;
import orderManagement.TradeStateManager;

/**
 * CONFIGURATOR 
 * Concrete implementation of DataConfigurator for the equity market.
 * It reads the CSV file generated by the Walk-Forward Analysis (WFA) in Python 
 * just once and generates a list of configurations ready for trading.
 * It integrates local state overrides for open positions and recovers orphan trades 
 * to prevent execution deadlocks if a pair disappears from the radar.
 * 
 * @author Davide Cortivo
 */
public class Configurator implements DataConfigurator {
    private String pairName;
    private Contract leg1;
    private Contract leg2;
    private double halfLife;
    private double hedgeRatio;
    private boolean isAcceptable;
    private double histES;
    private double spreadMean;
    private double spreadStdDev;
    private double intercept;
    
    /**
     * PRIVATE CONSTRUCTOR. 
     * Objects are now instantiated exclusively by loadAllPairs 
     * after parsing the CSV file.
     */
    private Configurator (String pairName, Contract leg1, Contract leg2, double halfLife, double hedgeRatio, boolean isAcceptable, double histES, double spreadMean, double spreadStdDev, double intercept) {
        this.pairName = pairName;
        this.leg1 = leg1;
        this.leg2 = leg2;
        this.halfLife = halfLife;
        this.hedgeRatio = hedgeRatio;
        this.isAcceptable = isAcceptable;
        this.histES = histES; 
        this.spreadMean = spreadMean;
        this.spreadStdDev = spreadStdDev;
        this.intercept = intercept;
    }
    
    /**
     * Generically reads any CSV file into a raw matrix of strings.
     * This method is completely decoupled from any trading strategy logic.
     * 
     * @param filePath The path to the target CSV file.
     * @return A list containing rows of raw string arrays.
     * @throws Exception If file I/O operations fail.
     */
    private static List<String[]> readRawCsv(String filePath) throws Exception {
        List<String[]> rawRows = new ArrayList<>();
        
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] columns = line.split(",(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)");
                rawRows.add(columns);
            }
        }
        return rawRows;
    }
    
    /**
     * Reads the Python CSV output and instantiates the portfolio configurations.
     * Integrates local state overrides for open positions and recovers orphan trades 
     * to prevent execution deadlocks if a pair disappears from the radar.
     * 
     * @param filePath     Absolute path to the Python WFA output CSV.
     * @param stateManager The local state manager holding data for open positions.
     * @return A list of ready-to-trade DataConfigurator objects.
     */
    public static List<DataConfigurator> loadAllPairs(String filePath, TradeStateManager stateManager) throws Exception {
        List<DataConfigurator> portfolio = new ArrayList<>();
    
        // Extract the text fields generically without financial constraints
        List<String[]> rawDataMatrix = readRawCsv(filePath);
        
        if (rawDataMatrix.isEmpty()) {
            return portfolio; 
        }

        // Dynamic extraction of header (first row of CSV)
        String[] headerRow = rawDataMatrix.get(0);
        Map<String, Integer> headerMap = new HashMap<>();
        for (int i = 0; i < headerRow.length; i++) {
            headerMap.put(headerRow[i].replace("\"", "").trim(), i);
        }
      
        Set<String> processedPairs = new HashSet<>();

        // 1. STANDARD PROCESSING FROM PYTHON CSV
        // Loop through the raw data rows
        for (int i = 1; i < rawDataMatrix.size(); i++) {
            String[] columns = rawDataMatrix.get(i);
            
         // EXTRACT THE PAIR NAME FIRST AND CHECK FOR ACTIVE POSITIONS
            String currentPair = getColumnValue(columns, headerMap, "Pair").trim();
            TradeStateManager.FrozenStructure activeState = stateManager.getFrozenStructure(currentPair);
            
            // Extract and clean raw data strings
            String acceptableStr = getColumnValue(columns, headerMap, "Robust_All_Windows").trim().toLowerCase();
            boolean isAcceptable = acceptableStr.equals("yes") || acceptableStr.equals("true");

            // We process acceptable pairs.
            if (isAcceptable || activeState != null) {
                processedPairs.add(currentPair);

                String leg1Str = getColumnValue(columns, headerMap, "Leg1").trim();
                String leg2Str = getColumnValue(columns, headerMap, "Leg2").trim();
                
                double ratio = Double.parseDouble(getColumnValue(columns, headerMap, "Scanner_Beta").trim());
                double hLife = Double.parseDouble(getColumnValue(columns, headerMap, "Half_Life_Days").trim());
                double histES = Double.parseDouble(getColumnValue(columns, headerMap, "Historical_ES_Pct").trim());
                double spreadMean = Double.parseDouble(getColumnValue(columns, headerMap, "Spread_Mean").trim());
                double spreadStdDev = Double.parseDouble(getColumnValue(columns, headerMap, "Spread_Std").trim());
                double intercept = Double.parseDouble(getColumnValue(columns, headerMap, "Intercept").trim());
                
                // THE HYBRID OVERRIDE 
                if (activeState != null) {
                    // Force the frozen direction parameters to avoid rebalancing
                    ratio = activeState.beta;
                    intercept = activeState.intercept;
                    // Update the local backup with fresh volatility metrics from Python
                    stateManager.updateVolatilityBackup(currentPair, spreadMean, spreadStdDev);
                    System.out.println("[CONFIGURATOR] OVERRIDE: Frozen Beta/Alpha loaded, fresh volatility injected for " + currentPair);
                }

                Contract leg1Contract = createStockContract(leg1Str, "EUR");
                Contract leg2Contract = createStockContract(leg2Str, "EUR");

                // Pack everything into the final object configuration instance
                Configurator config = new Configurator(currentPair, leg1Contract, leg2Contract, hLife, ratio, isAcceptable, histES, spreadMean, spreadStdDev, intercept);
                portfolio.add(config);
            }
        }

        // 2. ORPHAN TRADES RECOVERY 
        // If an open trade disappeared from Python's CSV entirely (e.g. script failed), 
        // we MUST reconstruct it using the local backup, otherwise the position remains locked in IBKR.
        Map<String, TradeStateManager.FrozenStructure> allActiveStates = stateManager.getAllActiveStates();
        for (Map.Entry<String, TradeStateManager.FrozenStructure> entry : allActiveStates.entrySet()) {
            String ghostPair = entry.getKey();
            
            if (!processedPairs.contains(ghostPair)) {
                System.out.println("[CONFIGURATOR] CRITICAL WARNING: Recovering Orphan Trade for " + ghostPair + ". Using backup volatility.");
                TradeStateManager.FrozenStructure ghostState = entry.getValue();
                
                String[] legs = ghostPair.split("/"); 
                Contract leg1Contract = createStockContract(legs[0], "EUR");
                Contract leg2Contract = createStockContract(legs[1], "EUR");

                // Reconstruct using solely the frozen data and backup metrics
                Configurator ghostConfig = new Configurator(
                    ghostPair, leg1Contract, leg2Contract, 
                    10.0, // Dummy Half-Life (not needed for exit execution)
                    ghostState.beta, 
                    false,
                    0.0, // Dummy histES
                    ghostState.lastMean, ghostState.lastStdDev,
                    ghostState.intercept
                );
                portfolio.add(ghostConfig);
            }
        }

        return portfolio;
    }
    
    /**
     * Helper to extract data with the column header
     */
    private static String getColumnValue(String[] columns, Map<String, Integer> headerMap, String columnName) throws Exception {
        Integer index = headerMap.get(columnName);
        if (index == null || index >= columns.length) {
            throw new Exception("[CONFIGURATOR - ERROR] Missing or out-of-bounds column header: '" + columnName + "'");
        }
        return columns[index].replace("\"", "").trim();
    }

    /**
     * Utility method to create a Contract object specifically configured 
     * for the equity market via Interactive Brokers API.
     */
    private static Contract createStockContract(String symbol, String currency) {
        Contract contract = new Contract();
        
        // it cleans the tickers from Yahoo finance (it erases .MI, .DE...)
        if (symbol.contains(".")) {
            symbol = symbol.substring(0, symbol.indexOf('.'));
        }
        
        contract.symbol(symbol);
        contract.secType("STK");       // Identifies the instrument as a Stock
        contract.exchange("SMART");    // Smart routing to the best available exchange
        contract.currency(currency);   // Settlement currency
        return contract;
    }

    // Getters
    @Override
    public String getPairName() {
        return pairName;
    }

    @Override
    public Contract getLeg1() {
        return leg1;
    }

    @Override
    public Contract getLeg2() {
        return leg2;
    }

    @Override
    public double getHedgeRatio() {
        return hedgeRatio;
    }

    @Override
    public boolean isAcceptable() {
        return isAcceptable;
    }

    @Override
    public double getHalfLife() {
        return halfLife;
    }

    @Override
    public double getHistoricalES() {
        return histES;
    }

    @Override
    public double getMean() {
        return spreadMean;
    }

    @Override
    public double getStdDev() {
        return spreadStdDev;
    }

    @Override
    public double getIntercept() {
        return intercept; 
    }
}
